// booth_ctrl_moore.sv - Moore controller of the skip-capable Booth multiplier.
// Generated by scripts/emit_sv.py from scripts/fsms.py - do not edit by hand.
// Flip-flops: SR, logic: minimal SOP (exact two-level minimisation with don't-cares),
// next-state 10 two-input gates, outputs 6 two-input gates.
// State encoding:
//   INIT   = 000
//   S00    = 011
//   S01    = 001
//   S10    = 111
//   S11    = 101
//   END    = 100
// EX_OP is a don't-care once COMPLETED is high (the datapath is frozen) and in END.

module booth_ctrl_moore (
  input  logic       clk,
  input  logic       rst,           // synchronous, to INIT
  input  logic       shift_in,      // multiplier bit 1 (the next bit to enter the window)
  input  logic       current_shift, // bit 0 of the value being loaded (selects S00 / S10 after INIT)
  input  logic       completed,     // all shifts done: go to END
  output logic [1:0] ex_op,         // 00 init, 01 add, 10 subtract, 11 shift
  output logic       done,
  output logic       init
);
  logic [2:0] q, qn;
  logic r0, r1, r2, s0, s1, s2;
  logic ex1, ex0;
  assign s2     = (qn[0] & current_shift) | completed | (q[1] & shift_in);  // 4 gates
  assign r2     = (qn[1] & q[0] & ~shift_in & ~completed);  // 3 gates
  assign s1     = (qn[2] & ~completed);  // 1 gates
  assign r1     = completed | q[2];  // 1 gates
  assign s0     = (qn[2] & ~completed);  // 1 gates
  assign r0     = completed;  // 0 gates
  assign ex1    = q[1] | q[2];  // 1 gates
  assign ex0    = (qn[1] & q[0]) | (qn[2] & q[0]);  // 3 gates
  assign done   = (q[2] & qn[0]);  // 1 gates
  assign init   = (qn[2] & qn[0]);  // 1 gates

  sr_ff u_q2 (.clk, .s(s2 & ~rst), .r(r2 | rst), .q(q[2]), .qn(qn[2]));
  sr_ff u_q1 (.clk, .s(s1 & ~rst), .r(r1 | rst), .q(q[1]), .qn(qn[1]));
  sr_ff u_q0 (.clk, .s(s0 & ~rst), .r(r0 | rst), .q(q[0]), .qn(qn[0]));
  assign ex_op = {ex1, ex0};
endmodule
